#!/usr/bin/env node
/**
 * my-error status line segment — a wrapper, never a replacement.
 *
 * WHY A WRAPPER
 * Claude Code runs exactly one `statusLine` command, so a plugin that wants a
 * segment there has two options: edit whatever script already owns the bar, or
 * wrap it. Editing is wrong here for a concrete reason rather than a stylistic
 * one — the bar in this environment is generated by a file its own framework
 * regenerates on setup, so an edit is silently reverted the next time that
 * framework runs, and the segment disappears with no error anywhere. So this
 * process runs the existing command as a child, takes its stdout verbatim,
 * appends one short segment, and prints the result.
 *
 * WHY IT DOES NOT COMPUTE ANYTHING ITSELF
 * Health, freshness and the data directory come from `my-error-state.cjs`, the
 * same module the watchdog uses; the numbers in it come from the plugin's own
 * `collect_metrics` via the beacon. This file owns exactly one thing the
 * watchdog does not: how to say all of that in four tokens. Everything else
 * would be a competing definition.
 *
 * WHY IT NEVER SPAWNS
 * A status line is redrawn constantly, so the cost of this segment has to be a
 * couple of file reads and nothing else. It asks the shared module for the
 * no-spawn answer, which prefers the watchdog's cached data directory and falls
 * back to the canonical path — and reports degraded health rather than
 * asserting a location it could not verify.
 *
 * SURVIVAL ORDER
 * The wrapped command's output is never withheld because of anything that
 * happens here. If the beacon is missing, unreadable, malformed or stale, the
 * existing bar still prints and the segment degrades to a marker. If the
 * wrapped command itself fails, the segment still prints, with a short note
 * that the other component is down. Nothing in this file may make the editor's
 * status line unusable — that is a worse outcome than showing no metrics.
 *
 * WHY IT LEAVES A TRACE
 * Running this script by hand proves nothing about the editor that is already
 * running (see ERR-0016). So each run stamps a small invocation beacon, at most
 * once every few seconds, recording who invoked it and what it printed. That
 * file is the only evidence that the *live* status bar — not a shell — is
 * executing this code.
 *
 * CONFIGURATION
 *   MY_ERROR_STATUSLINE_WRAP  shell command producing the existing status line.
 *                             Receives the same stdin. Optional: with no value
 *                             this prints the my-error segment alone.
 *   MY_ERROR_DATA_DIR         overrides the canonical data directory.
 */
'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const SEPARATOR = '  │  ';
// Generous on purpose. A status line that shells out to `git status` — most of
// them do — occasionally blocks for seconds under index contention, and cutting
// it off there costs the user their whole bar to save a fraction of a second.
// Measured: the bar wrapped here runs in ~60 ms, with one 3 s outlier in 300
// samples taken under load.
const WRAP_TIMEOUT_MS = 5000;
const TRACE = path.join(os.homedir(), '.claude', 'watchdogs', '.my-error-statusline.json');
const TRACE_INTERVAL_MS = 5000;

/** The shared reader. Its absence is a real failure state, not a crash: the
 *  installer copies three files and someone may have copied one. */
let state = null;
let stateError = null;
try {
  state = require('./my-error-state.cjs');
} catch (err) {
  stateError = String((err && err.message) || err);
}

/**
 * The segment, as {text, level}. Never throws: every failure mode degrades to a
 * marker, because a status line that crashes takes the whole bar with it.
 *
 * Three levels only, because a status bar is not a report:
 *   ✅ healthy · ⚠️ present but not trustworthy · ❌ not there at all
 * Anything finer belongs in /my-error:doctor.
 */
function segment() {
  if (!state) return { text: '🧠 ME ❌', level: 'down', detail: `state module: ${stateError}` };

  let health;
  try {
    health = state.structuralHealth({ allowSpawn: false, writeCache: false });
  } catch (err) {
    return { text: '🧠 ME ⚠️', level: 'degraded', detail: String((err && err.message) || err) };
  }

  // Not installed and not enabled are the two "it is not there" cases. Every
  // other problem is something present that cannot be trusted.
  if (!health.installation) return { text: '🧠 ME ❌', level: 'down', detail: 'não instalado' };
  if (!health.enabled) return { text: '🧠 ME ❌', level: 'down', detail: 'desabilitado' };

  let live;
  try {
    live = state.liveState(health, null);
  } catch (err) {
    return { text: '🧠 ME ⚠️', level: 'degraded', detail: String((err && err.message) || err) };
  }

  const beacon = live.beacon;
  // The version the *running* plugin declares, which is not necessarily the one
  // on disk. When they disagree, the installed code is not the code in use —
  // the exact failure ERR-0016 describes — so say so instead of picking one.
  const runtimeVersion = beacon && typeof beacon.version === 'string' ? beacon.version : null;
  const installedVersion = typeof health.version === 'string' ? health.version : null;
  const versionMismatch = !!(runtimeVersion && installedVersion && runtimeVersion !== installedVersion);
  const version = runtimeVersion || installedVersion || '?';

  const problems = [];
  if (!health.hooks_registered) problems.push('hooks');
  if (!live.database_readable) problems.push('db');
  if (!beacon) problems.push('beacon');
  if (live.stale) problems.push('defasado');
  if (health.data_dir_guessed) problems.push('caminho');
  if (versionMismatch) problems.push(`inst ${installedVersion}`);

  const mark = problems.length ? '⚠️' : '✅';
  const parts = [`🧠 ME ${mark} ${version}`];

  const m = live.metrics;
  const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
  if (m) {
    if (typeof m.mode === 'string') parts.push(m.mode);
    const lessons = num(m.lessons_active);
    const cross = num(m.cross_project_recalls);
    if (lessons !== null) parts.push(`L${lessons}`);
    if (cross !== null) parts.push(`X${cross}`);
  }
  if (problems.length) parts.push(problems.join('/'));

  return {
    text: parts.join(' · '),
    level: problems.length ? 'degraded' : 'ok',
    detail: problems.join('/') || 'ok',
    version, runtime_version: runtimeVersion, installed_version: installedVersion,
  };
}

/** Run the pre-existing status line with the same stdin it would have received. */
function wrapped(stdin) {
  const cmd = process.env.MY_ERROR_STATUSLINE_WRAP;
  if (!cmd || !cmd.trim()) return { text: '', failed: false, configured: false };
  try {
    const res = spawnSync(cmd, {
      shell: true,
      input: stdin,
      encoding: 'utf8',
      timeout: WRAP_TIMEOUT_MS,
      maxBuffer: 1024 * 1024,
    });
    const text = (res.stdout || '').trim();
    // Partial output from a failing child is still worth showing: a status line
    // that wrote its content and then exited non-zero is more useful on screen
    // than an empty bar.
    if (res.error || res.status !== 0) return { text, failed: true, configured: true };
    return { text, failed: false, configured: true };
  } catch {
    return { text: '', failed: true, configured: true };
  }
}

/** The live-instance beacon. Throttled, best-effort, never load-bearing. */
function trace(record) {
  try {
    const prev = fs.statSync(TRACE).mtimeMs;
    if (Date.now() - prev < TRACE_INTERVAL_MS) return;
  } catch { /* first run */ }
  try {
    fs.mkdirSync(path.dirname(TRACE), { recursive: true });
    fs.writeFileSync(TRACE, JSON.stringify(record));
  } catch { /* evidence is nice to have, never required */ }
}

function main() {
  const t0 = process.hrtime.bigint();
  let stdin = '';
  try {
    stdin = fs.readFileSync(0, 'utf8');
  } catch {
    // No stdin is survivable: the child gets an empty document, and this file's
    // own segment does not depend on the payload at all.
  }

  // Parsed only for the trace. A malformed payload must not change what is
  // printed, because the segment never needed the payload in the first place.
  let event = {};
  try { event = JSON.parse(stdin) || {}; } catch { event = {}; }

  const base = wrapped(stdin);
  const t1 = process.hrtime.bigint();
  const seg = segment();
  const t2 = process.hrtime.bigint();

  const pieces = [];
  if (base.text) pieces.push(base.text);
  // A failed wrapped command must be visible rather than silently absent —
  // otherwise the bar simply loses half its content with no explanation.
  else if (base.failed) pieces.push('▊ statusline ⚠️');
  pieces.push(seg.text);
  // A multi-line bar gets its own final line rather than a longer last line:
  // appending to a line that is already near the terminal width is how a short
  // segment turns into a wrapped, unreadable one. Single-line bars stay single.
  const joiner = pieces.length > 1 && pieces[0].includes('\n') ? '\n' : SEPARATOR;
  const out = pieces.join(joiner);

  process.stdout.write(out);

  trace({
    at: new Date().toISOString(),
    pid: process.pid,
    ppid: process.ppid,
    session_id: typeof event.session_id === 'string' ? event.session_id : null,
    cwd: typeof event.cwd === 'string' ? event.cwd : null,
    segment: seg.text,
    level: seg.level,
    detail: seg.detail,
    runtime_version: seg.runtime_version || null,
    installed_version: seg.installed_version || null,
    wrapped: { configured: base.configured, failed: base.failed, chars: base.text.length },
    ms: { wrapped: Number(t1 - t0) / 1e6, segment: Number(t2 - t1) / 1e6 },
    line: out,
  });
}

// Exported so the tests and the benchmark can exercise the segment without
// paying for a process per sample — measuring `node` startup would tell us
// about node, not about this file.
module.exports = { segment, wrapped, SEPARATOR, TRACE };

if (require.main === module) {
  try {
    main();
  } catch (err) {
    // Last resort. Printing nothing would blank the user's status line; printing
    // a marker keeps the failure visible and the interface usable.
    process.stdout.write(`🧠 ME ⚠️ ${String((err && err.message) || err).slice(0, 60)}`);
  }
}
